        public PuzzleMechanismLogic18(string id, string name, int tier = 1, double magnitude = 10.0)
        {
            Id = id;
            Name = name;
            LevelTier = tier;
            BaseMagnitude = magnitude;
            MultiplierValue = 1.0 + (tier * 0.15);
            IsEnabled = true;
            TagCollection.Add("PuzzleMechanismLogic");
            NumericParameters["Cooldown"] = 5.0 + tier;
            NumericParameters["Radius"] = 2.5 + tier * 0.5;
            NumericParameters["Cost"] = 15.0 + tier * 2;
        }


